import os, xml.etree.ElementTree as ET, numpy as np
base='/opt/VLABench/VLABench/assets/obj/meshes'
files={'box':'containers/boxes/giftbox/giftbox_1/giftbox.xml','donald':'toys/disney/mickey/donald/donald_0/donald.xml','daisy':'toys/disney/mickey/daisy/daisy_duck_1/play_station_2_-_disney_move_-_daisy_duck.xml','robin':'toys/onepiece/robin/robin_0/nico_robin.xml','luffy':'toys/onepiece/luffy/luffy_0/luffy_one_piece.xml'}
for name,rel in files.items():
 p=os.path.join(base,rel); root=ET.parse(p).getroot(); lo=[]; hi=[]
 for m in root.findall('.//mesh'):
  path=os.path.normpath(os.path.join(os.path.dirname(p),m.attrib['file']))
  scale=np.array([float(x) for x in m.attrib.get('scale','1 1 1').split()])
  verts=[]
  try:
   with open(path,errors='ignore') as f:
    for line in f:
     if line.startswith('v '):
      vals=line.split()[1:4]
      if len(vals)==3: verts.append([float(x) for x in vals])
  except OSError: continue
  if verts:
   a=np.asarray(verts)*scale; lo.append(a.min(0)); hi.append(a.max(0))
 if lo:
  a=np.min(lo,axis=0); b=np.max(hi,axis=0)
  print(name,'local min',np.round(a,4).tolist(),'max',np.round(b,4).tolist(),'size',np.round(b-a,4).tolist())
 else: print(name,'no mesh bounds')
 if name=='box':
  for g in root.findall('.//geom'):
   if g.attrib.get('class')=='collision': print(' wall geom',g.attrib)
